import{_ as o,b as a,e as n,a8 as i}from"./chunks/framework.CNHV3T2x.js";const t="data:image/png;base64,",r="data:image/png;base64,",s="data:image/png;base64,",d="data:image/png;base64,",A="data:image/png;base64,",c="data:image/png;base64,",f=JSON.parse('{"title":"Naming conventions","description":"","frontmatter":{"date":1787994169000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/naming-conventions.md","filePath":"guide/naming-conventions.md","lastUpdated":1787994169000,"timestamp":1787994169000,"datetime":"2026-08-29T09:02:49.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),l={name:"guide/naming-conventions.md"};function h(g,e,m,p,b,w){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="naming-conventions" tabindex="-1">Naming conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming conventions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>Graphics32 follows standard Delphi/FPC identifier naming practices:</p><table tabindex="0"><thead><tr><th>Category</th><th>Prefix</th><th>Example</th></tr></thead><tbody><tr><td><strong>Classes</strong></td><td><code>T</code></td><td><code>TBitmap32</code>, <code>TImage32</code>, <code>TCustomSampler</code></td></tr><tr><td><strong>Interfaces</strong></td><td><code>I</code></td><td><code>IBackend</code>, <code>INotify</code></td></tr><tr><td><strong>Types / Records</strong></td><td><code>T</code></td><td><code>TColor32</code>, <code>TFloatPoint</code>, <code>TRect</code></td></tr><tr><td><strong>Color Constants</strong></td><td><code>cl</code></td><td><code>clWhite32</code>, <code>clRed32</code></td></tr><tr><td><strong>Global Functions</strong></td><td>PascalCase</td><td><code>Color32</code>, <code>RedComponent</code>, <code>Intensity</code></td></tr></tbody></table><h2 id="line-and-pixel-methods" tabindex="-1">Line and Pixel methods <a class="header-anchor" href="#line-and-pixel-methods" aria-label="Permalink to &quot;Line and Pixel methods&quot;">​</a></h2><p>The <a href="/api/GR32/TBitmap32/">TBitmap32</a> class provides a large number of methods for single pixel access and single pixel width line drawing. While the prefix of these methods indicate <em>what</em> they do (draw a line, access a pixel, etc.), the postfix denotes <em>how</em> they behave. The methods can include one or more of the following postfixes:</p><table tabindex="0"><thead><tr><th>Postfix</th><th>Name</th><th>Description</th><th>Sample (magnified x4)</th><th>Examples</th></tr></thead><tbody><tr><td>(none)</td><td></td><td>Methods without modifiers offer maximum performance.<br>Lines and pixels are rendered without anti-aliasing and without color blending.<br>No clipping is performed so coordinates are expected to be within bitmap boundaries. Out of bounds coordinates can cause access violations and memory overwrites.</td><td><img src="'+t+'" alt=""></td><td><code>Line</code><br><code>HorzLine</code><br><code>Pixel</code><br><code>FillRect</code></td></tr><tr><td>S</td><td>Safe</td><td>Clipping is performed when coordinates extend beyond bitmap boundaries.<br>This modifier can be combined with any <strong>one</strong> of the anti-aliasing or transparent modifiers below (T, A, X or F) and also with the stippling (P) modifier.</td><td><img src="'+t+'" alt=""></td><td><code>LineS</code><br><code>LineToS</code><br><code>PixelS</code></td></tr><tr><td>T</td><td>Transparent</td><td>Semi-transparent pixels are merged onto the background image (though still without anti-aliasing).</td><td><img src="'+r+'" alt=""></td><td><code>LineTS</code><br><code>LineToTS</code><br><code>FillRectTS</code></td></tr><tr><td>A</td><td>Anti-aliased</td><td>Uses a modified version of <a href="https://en.wikipedia.org/wiki/Bresenham%27s_line_algorithm" target="_blank" rel="noreferrer">Bresenham’s algorithm</a> known as <a href="https://en.wikipedia.org/wiki/Xiaolin_Wu%27s_line_algorithm" target="_blank" rel="noreferrer">Wu’s antialiasing</a>.</td><td><img src="'+s+'" alt=""></td><td><code>LineA</code><br><code>LineAS</code></td></tr><tr><td>X</td><td>Fixed</td><td>Coordinates are in fixed point (<code>TFixed</code>) format.<br>These methods also employ a more sophisticated anti-aliasing algorithm than that used in the ‘A’ methods above.</td><td><img src="'+d+'" alt=""></td><td><code>LineX</code><br><code>LineXS</code><br><code>PixelXS</code></td></tr><tr><td>F</td><td>Float</td><td>Coordinates are in floating point (<code>TFloat</code>) format.<br>These methods employ the same anti-aliasing algorithm used in the ‘X’ methods.</td><td><img src="'+d+'" alt=""></td><td><code>LineFS</code><br><code>PixelFS</code></td></tr><tr><td>P</td><td>Stippling</td><td>Lines are drawn using a <a href="./line-patterns">stippling pattern</a>.<br>This modifier must be combined with either the ‘X’ or ‘F’ modifiers above.</td><td><img src="'+A+'" alt=""></td><td><code>LineFSP</code><br><code>LineXSP</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Note</p><p>For lines, all the methods listed above draw line segments that are <strong>a single pixel wide</strong>. To draw thicker lines, see the <code>Polyline</code> and <code>PolyPolyline</code> functions in the <a href="/api/GR32_Polygons/">GR32_Polygons</a> unit. Those functions also produce better anti-aliased blending over fully transparent backgrounds (when compared with X &amp; F modified methods above). <img src="'+c+'" alt=""></p></div><h2 id="blend-functions" tabindex="-1">Blend functions <a class="header-anchor" href="#blend-functions" aria-label="Permalink to &quot;Blend functions&quot;">​</a></h2><p>Most blend functions are named using a scheme that clearly identify how they operate:</p><table tabindex="0"><thead><tr><th>Name</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>*Reg*</td><td><code>BlendReg</code></td><td>The result foreground color is returned as the function <code>Result</code>.</td></tr><tr><td>*Mem*</td><td><code>BlendMem</code></td><td>The result foreground color is returned in the <strong>F</strong> parameter.</td></tr><tr><td>Ex*</td><td><code>MergeRegEx</code></td><td>The the foreground alpha is scaled with a master alpha value.</td></tr><tr><td>*Mems*</td><td><code>BlendMems</code></td><td>Apply a single foreground color onto an array of background colors.</td></tr><tr><td>*Line*</td><td><code>MergeLine</code></td><td>Apply an array of foreground colors onto an array of background colors.</td></tr><tr><td>*RGB*</td><td><code>BlendMemRGB</code></td><td>Operate independently on each color channel using separate alpha values.</td></tr><tr><td>*Line1*</td><td><code>MergeLine1</code></td><td>Deprecated. Same as *Mems*.</td></tr></tbody></table>',11)])])}const u=o(l,[["render",h]]);export{f as __pageData,u as default};
